pub open spec fn inv_local_updates_wf(&self, update: UpdateState<DT>) -> bool {
    match update {
        UpdateState::Init { op } => { true },
        UpdateState::Placed { op: _, idx } => {
            &&& self.log.contains_key(idx)
            &&& idx < self.tail
        },
        UpdateState::Applied { ret, idx } => {
