pub open spec fn QueueRidsUpdateDone<DT: Dispatch>(
    queued_ops: Seq<ReqId>,
    localUpdates: Map<ReqId, UpdateState<DT>>,
    bound: nat,
) -> bool
    recommends
        0 <= bound <= queued_ops.len(),
{
