        have combiner >= [ node_id => let CombinerState::Loop{ queued_ops, lversion, tail, idx } ];

        require(lversion == tail);
        assert(idx == queued_ops.len()) by {
            // assert(pre.wf_combiner_for_node_id(node_id));
            // assert(lversion == tail);
