             queue,
             new_log,
             queueIndex,
             logIndexLower + 1,
             logIndexUpper + 1,
             node_id,
             new_updates,
         ));
     } else {
         assert(new_log.index(logIndexLower) === log.index(logIndexLower));
         if new_log.index(logIndexLower).node_id == node_id {
             LogRangeMatchesQueue_append_other_augment(
                 queue,
                 log,
                 new_log,
                 queueIndex + 1,
                 logIndexLower + 1,
                 logIndexUpper,
                 node_id,
                 updates,
                 new_updates,
                 new_rid,
                 log_entry,
             );
             assert(LogRangeMatchesQueue(
                 queue,
                 new_log,
                 queueIndex,
                 logIndexLower,
                 logIndexUpper + 1,
                 node_id,
                 new_updates,
             ));
         } else {
             LogRangeMatchesQueue_append_other_augment(
                 queue,
                 log,
                 new_log,
                 queueIndex,
                 logIndexLower + 1,
                 logIndexUpper,
                 node_id,
                 updates,
                 new_updates,
                 new_rid,
                 log_entry,
             );
         }
     }
